T='''"use client";
import { useRef, useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const lesson = __DATA__;
export default function Demo({slug}:{slug:string}) {
 const [seen,setSeen]=useState([false,false]);
 const recorded=useRef([false,false]);
 return <Lesson slug={slug} predict={{question:lesson.question,options:lesson.options,answer:lesson.answer}} exploreHint="Open both states and compare what each shows." minInteractions={2} reveal={()=><p>{lesson.explanation}</p>}>
 {({locked,interact})=><div><svg viewBox="0 0 340 170" className="stage-svg" role="img" aria-label={seen.every(Boolean)?lesson.shownLabel:seen.some(Boolean)?lesson.label + " Visible state: " + lesson.labels[seen[0] ? 0 : 1] + "." : "Both diagram states are hidden until you explore."}>
 <rect x="4" y="5" width="158" height="154" rx="12" fill="var(--bg-2)" stroke="var(--line)"/><rect x="178" y="5" width="158" height="154" rx="12" fill="var(--bg-2)" stroke="var(--line)"/>
 {seen[0] && <g transform="translate(12 9)">__S1__</g>}{seen[1] && <g transform="translate(186 9)">__S2__</g>}
 {seen[0] && <text x="82" y="150" textAnchor="middle" fill="var(--fg)" fontSize="13">{lesson.labels[0]}</text>}{seen[1] && <text x="256" y="150" textAnchor="middle" fill="var(--fg)" fontSize="13">{lesson.labels[1]}</text>}
 </svg><Row><Control style={{minWidth:44,minHeight:44}} disabled={locked || seen[0]} onClick={()=>{if(recorded.current[0]) return; recorded.current[0]=true; setSeen(v=>[true,v[1]]);interact();}}>Open first</Control><Control style={{minWidth:44,minHeight:44}} disabled={locked || seen[1]} onClick={()=>{if(recorded.current[1]) return; recorded.current[1]=true; setSeen(v=>[v[0],true]);interact();}}>Open second</Control></Row></div>}
 </Lesson>;
}
'''
for c in C:
 slug='zoo-invert-'+c['slug'];out=Path('src/demos/life')/slug
 if out.exists():raise ValueError(f'Existing lesson: {slug}')
 out.mkdir(parents=True)
 label=c['lim']; lesson={'question':c['q'],'options':c['opts'],'answer':c['answer'],'explanation':c['why'],'labels':c['lab'],'label':label,'shownLabel':label+' '+c['why']}
 (out/'Demo.tsx').write_text(T.replace('__DATA__',json.dumps(lesson,ensure_ascii=False,indent=2)).replace('__S1__',c['s1']).replace('__S2__',c['s2']))
 source='Unverified starting points, not verified sources for this specific claim: Smithsonian Ocean https://ocean.si.edu/ocean-life/invertebrates ; OpenStax Biology 2e https://openstax.org/books/biology-2e . Exact claim-level sources and species-specific qualifications require independent review.'
 meta={'slug':slug,'title':c['title'],'hook':c['hook'],'domain':'life','concept':slug,'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals can have structures and life stages that differ from humans.'],'doesNotKnow':[c['why']]},'misconception':'The observations in this scenario require a different interpretation.','objective':c['q'],'claims':[{'id':f'life.{slug}.c1','text':c['hook']+' '+c['q']+' '+c['why']+' '+'; '.join(c['lab']),'support':'source','source':source,'status':'unverified'},{'id':f'life.{slug}.c2','text':c['lim'],'support':'convention','source':'Drawing and stated scenario convention.','status':'unverified'},{'id':f'life.{slug}.c3','text':c['rq']+' '+c['rw'],'support':'source','source':source,'status':'unverified'}],'confidence':'','recall':{'question':c['rq'],'options':c['ro'],'answer':0,'why':c['rw']},'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
 (out/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
print('Generated',len(C),'drafts:',', '.join(str(c['n']) for c in C))
